create table if not exists public.primary_staff_qualifications (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,qualification_title text not null check(length(trim(qualification_title)) between 2 and 180),institution text,field_of_study text,qualification_level text not null check(qualification_level in ('certificate','diploma','bachelors','postgraduate_diploma','masters','doctorate','other')),award_date date,certificate_reference text,verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected')),verification_notes text,verified_by uuid references auth.users(id),verified_at timestamptz,recorded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.primary_staff_attendance (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,attendance_date date not null,status text not null check(status in ('present','absent','late','excused')),check_in time,check_out time,notes text,recorded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(staff_profile_id,attendance_date),check(check_out is null or check_in is null or check_out>=check_in));
create table if not exists public.primary_staff_leave_requests (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,staff_profile_id uuid not null references public.staff_profiles(id) on delete cascade,leave_type text not null check(leave_type in ('annual','sick','maternity','paternity','compassionate','study','unpaid','other')),start_date date not null,end_date date not null,reason text not null check(length(trim(reason)) between 3 and 2000),status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),review_notes text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,recorded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create index if not exists primary_staff_qual_school_staff_idx on public.primary_staff_qualifications(school_id,staff_profile_id);
create index if not exists primary_staff_qual_recorded_by_idx on public.primary_staff_qualifications(recorded_by);
create index if not exists primary_staff_qual_verified_by_idx on public.primary_staff_qualifications(verified_by);
create index if not exists primary_staff_attendance_school_date_idx on public.primary_staff_attendance(school_id,attendance_date desc);
create index if not exists primary_staff_attendance_staff_date_idx on public.primary_staff_attendance(staff_profile_id,attendance_date desc);
create index if not exists primary_staff_attendance_recorded_by_idx on public.primary_staff_attendance(recorded_by);
create index if not exists primary_staff_leave_school_status_idx on public.primary_staff_leave_requests(school_id,status,start_date);
create index if not exists primary_staff_leave_staff_date_idx on public.primary_staff_leave_requests(staff_profile_id,start_date desc);
create index if not exists primary_staff_leave_recorded_by_idx on public.primary_staff_leave_requests(recorded_by);
create index if not exists primary_staff_leave_reviewed_by_idx on public.primary_staff_leave_requests(reviewed_by);
alter table public.primary_staff_qualifications enable row level security; alter table public.primary_staff_qualifications force row level security;
alter table public.primary_staff_attendance enable row level security; alter table public.primary_staff_attendance force row level security;
alter table public.primary_staff_leave_requests enable row level security; alter table public.primary_staff_leave_requests force row level security;
revoke all on public.primary_staff_qualifications,public.primary_staff_attendance,public.primary_staff_leave_requests from public,anon,authenticated;
grant select,insert,update,delete on public.primary_staff_qualifications,public.primary_staff_attendance,public.primary_staff_leave_requests to authenticated;
create policy primary_staff_qual_read on public.primary_staff_qualifications for select to authenticated using(private.has_school_role(primary_staff_qualifications.school_id,array['owner','proprietor','school_admin','headteacher','deputy_headteacher','registrar']::text[]) or exists(select 1 from public.staff_profiles sp join public.school_memberships sm on sm.id=sp.membership_id where sp.id=primary_staff_qualifications.staff_profile_id and sp.school_id=primary_staff_qualifications.school_id and sm.user_id=auth.uid() and sm.is_active));
create policy primary_staff_qual_insert on public.primary_staff_qualifications for insert to authenticated with check(private.has_school_role(primary_staff_qualifications.school_id,array['owner','proprietor','school_admin','headteacher']::text[]) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_qualifications.staff_profile_id and sp.school_id=primary_staff_qualifications.school_id) and recorded_by=auth.uid());
create policy primary_staff_qual_update on public.primary_staff_qualifications for update to authenticated using(private.has_school_role(primary_staff_qualifications.school_id,array['owner','proprietor','school_admin','headteacher']::text[])) with check(private.has_school_role(primary_staff_qualifications.school_id,array['owner','proprietor','school_admin','headteacher']::text[]) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_qualifications.staff_profile_id and sp.school_id=primary_staff_qualifications.school_id));
create policy primary_staff_qual_delete on public.primary_staff_qualifications for delete to authenticated using(private.has_school_role(primary_staff_qualifications.school_id,array['owner','proprietor','school_admin','headteacher']::text[]));
create policy primary_staff_attendance_read on public.primary_staff_attendance for select to authenticated using(private.has_school_role(primary_staff_attendance.school_id,array['owner','proprietor','school_admin','headteacher','deputy_headteacher','registrar']::text[]) or exists(select 1 from public.staff_profiles sp join public.school_memberships sm on sm.id=sp.membership_id where sp.id=primary_staff_attendance.staff_profile_id and sp.school_id=primary_staff_attendance.school_id and sm.user_id=auth.uid() and sm.is_active));
create policy primary_staff_attendance_insert on public.primary_staff_attendance for insert to authenticated with check(private.has_school_role(primary_staff_attendance.school_id,array['owner','proprietor','school_admin','headteacher','deputy_headteacher']::text[]) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_attendance.staff_profile_id and sp.school_id=primary_staff_attendance.school_id and sp.is_active) and recorded_by=auth.uid());
create policy primary_staff_attendance_update on public.primary_staff_attendance for update to authenticated using(private.has_school_role(primary_staff_attendance.school_id,array['owner','proprietor','school_admin','headteacher']::text[])) with check(private.has_school_role(primary_staff_attendance.school_id,array['owner','proprietor','school_admin','headteacher']::text[]) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_attendance.staff_profile_id and sp.school_id=primary_staff_attendance.school_id and sp.is_active));
create policy primary_staff_attendance_delete on public.primary_staff_attendance for delete to authenticated using(private.has_school_role(primary_staff_attendance.school_id,array['owner','proprietor','school_admin','headteacher']::text[]));
create policy primary_staff_leave_read on public.primary_staff_leave_requests for select to authenticated using(private.has_school_role(primary_staff_leave_requests.school_id,array['owner','proprietor','school_admin','headteacher','deputy_headteacher','registrar']::text[]) or exists(select 1 from public.staff_profiles sp join public.school_memberships sm on sm.id=sp.membership_id where sp.id=primary_staff_leave_requests.staff_profile_id and sp.school_id=primary_staff_leave_requests.school_id and sm.user_id=auth.uid() and sm.is_active));
create policy primary_staff_leave_insert on public.primary_staff_leave_requests for insert to authenticated with check((private.has_school_role(primary_staff_leave_requests.school_id,array['owner','proprietor','school_admin','headteacher']::text[]) or exists(select 1 from public.staff_profiles sp join public.school_memberships sm on sm.id=sp.membership_id where sp.id=primary_staff_leave_requests.staff_profile_id and sp.school_id=primary_staff_leave_requests.school_id and sm.user_id=auth.uid() and sm.is_active)) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_leave_requests.staff_profile_id and sp.school_id=primary_staff_leave_requests.school_id and sp.is_active) and recorded_by=auth.uid() and status='pending');
create policy primary_staff_leave_update on public.primary_staff_leave_requests for update to authenticated using(private.has_school_role(primary_staff_leave_requests.school_id,array['owner','proprietor','school_admin','headteacher']::text[])) with check(private.has_school_role(primary_staff_leave_requests.school_id,array['owner','proprietor','school_admin','headteacher']::text[]) and exists(select 1 from public.staff_profiles sp where sp.id=primary_staff_leave_requests.staff_profile_id and sp.school_id=primary_staff_leave_requests.school_id));
create policy primary_staff_leave_delete on public.primary_staff_leave_requests for delete to authenticated using(private.has_school_role(primary_staff_leave_requests.school_id,array['owner','proprietor','school_admin']::text[]));
create or replace function public.manage_school_staff_profile(p_school_id uuid,p_membership_id uuid,p_staff_number text,p_employment_title text,p_employment_type text,p_hire_date date,p_is_active boolean,p_staff_profile_id uuid default null)
returns uuid language plpgsql set search_path=public,private as $function$
declare v_id uuid; v_role text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_school_role(p_school_id,array['owner','proprietor','school_admin','headteacher','deputy_headteacher']::text[]) then raise exception 'You do not have permission to manage staff'; end if;
 if nullif(trim(p_staff_number),'') is null then raise exception 'Staff number is required'; end if;
 if p_employment_type is not null and p_employment_type not in ('permanent','contract','temporary','volunteer') then raise exception 'Invalid employment type'; end if;
 select role into v_role from public.school_memberships where id=p_membership_id and school_id=p_school_id and is_active;
 if v_role is null then raise exception 'Select an active member of this school'; end if;
 if v_role not in ('teacher','class_teacher','academic_officer','bursar','school_admin','headteacher','deputy_headteacher') then raise exception 'This membership role cannot be registered as school staff'; end if;
 if p_staff_profile_id is null then insert into public.staff_profiles(school_id,membership_id,staff_number,employment_title,employment_type,hire_date,is_active) values(p_school_id,p_membership_id,trim(p_staff_number),nullif(trim(p_employment_title),''),p_employment_type,p_hire_date,coalesce(p_is_active,true)) returning id into v_id;
 else update public.staff_profiles set membership_id=p_membership_id,staff_number=trim(p_staff_number),employment_title=nullif(trim(p_employment_title),''),employment_type=p_employment_type,hire_date=p_hire_date,is_active=p_is_active where id=p_staff_profile_id and school_id=p_school_id returning id into v_id; if v_id is null then raise exception 'Staff profile not found for this school'; end if; end if;
 return v_id;
end $function$;
revoke all on function public.manage_school_staff_profile(uuid,uuid,text,text,text,date,boolean,uuid) from public,anon;
grant execute on function public.manage_school_staff_profile(uuid,uuid,text,text,text,date,boolean,uuid) to authenticated;
